initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT containing an initial Entity ${entity} 
        with an id set to ${entityId} 
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Merge Entity with Response Status Code set to 204     and
        Query Entity with Response Body containing en entity element with id set to 'entity_id=${entity_id}' and body content set to 'merge/building-non-edited.jsonld'
}

then {
    the SUT sends a valid Response for the operations:
        Merge Entity with Response Status Code set to 204     and
        Query Entity with Response Body containing en entity element with id set to 'entity_id=${entity_id}' and body content set to 'merge/building-attributes-edited.jsonld'
}

then {
    the SUT sends a valid Response for the operations:
        Merge Entity with Response Status Code set to 204     and
        Query Entity with Response Body containing en entity element with id set to 'entity_id=${entity_id}' and body content set to 'merge/building-with-relationship.jsonld'
}

then {
    the SUT sends a valid Response for the operations:
        Merge Entity with Response Status Code set to 204     and
        Query Entity with Response Body containing en entity element with id set to 'entity_id=${entity_id}' and body content set to 'merge/building-with-changed-airQualityLevel.jsonld'
}
